#!/bin/bash
# The 100 MiB agent (test/llm-agent-wide: d=512, 8 layers, context 128, untrained,
# generated by train_agent_gpt.py --blob --export-anyway) on every kernel and unit,
# under an edge memory bandwidth.  Builds each variant, records it under QEMU with
# the plugin, simulates it in Sniper, and prints cycles per token.
#   tools/llm/wide-sweep.sh <out dir> [bandwidth GB/s] [config ...]
# Needs SNIPER_RISCV_CC and SNIPER_QEMU_RISCV; configs default to all of:
#   fp32-rvv fp32-rvv4k fp32-ame32 fp32-ame32-nca w4-rvv w4-rvv4k
# (the 4k configs run a 4,096-bit vector unit over a 64-byte datapath: 32x fewer
# vector instructions than at 128 bits, each 8 cycles through the datapath).
set -u
ROOT=$(cd "$(dirname "$0")/../.." && pwd); OUT=${1:?out dir}; BW=${2:-25.6}; shift 2 2>/dev/null || shift $#
CONFIGS=${*:-"fp32-rvv fp32-rvv4k fp32-ame32 fp32-ame32-nca w4-rvv w4-rvv4k"}
CC=${SNIPER_RISCV_CC:?}; Q=${SNIPER_QEMU_RISCV:?}; P=$ROOT/build/release/lib/libsniper-qemu.so
CPU128=max,vlen=128,x-zvvmm=on,x-zvvfmm=on,x-zvvmtls=on
VEC4K=(-g perf_model/core/riscv/vector_bytes=512 -g perf_model/core/vector/datapath_bytes=64)
mkdir -p "$OUT"; cd "$ROOT"
# A quoted #include searches the source file's directory first, so the agent is
# compiled from a copy outside test/llm-agent: its headers and blobs then come
# from test/llm-agent-wide alone.
cp test/llm-agent/agent.c "$OUT/agent-wide.c"
build() { $CC --target=riscv64-linux-gnu -march=rv64gcv -mabi=lp64d -O2 -ffreestanding -nostdlib -static -fuse-ld=lld -Wl,-e,_start -I include -I test/llm-agent-wide "$@" "$OUT/agent-wide.c"; }
one() {
   local cfg=$1 flags= popt= gargs=() cpu=$CPU128
   case $cfg in
      fp32-rvv)        flags="-DUSE_RVV" ;;
      fp32-rvv4k)      flags="-DUSE_RVV"; cpu=${CPU128/vlen=128/vlen=4096}; gargs=("${VEC4K[@]}") ;;
      w4-rvv)          flags="-DUSE_W4" ;;
      w4-rvv4k)        flags="-DUSE_W4"; cpu=${CPU128/vlen=128/vlen=4096}; gargs=("${VEC4K[@]}") ;;
      fp32-ame32)      flags="-DUSE_AME -DAME_N=32"; popt=",ame_n=32"; gargs=(-g perf_model/core/riscv/ame_mma_issue_cycles=32) ;;
      fp32-ame32-nca)  flags="-DUSE_AME -DAME_N=32"; popt=",ame_n=32"; gargs=(-g perf_model/ame_tile/coupling=nca) ;;
      *) echo "unknown config $cfg"; return 1 ;;
   esac
   local g=$OUT/agent-$cfg t=$OUT/trace-$cfg d=$OUT/sim-$cfg
   build $flags -o $g > $OUT/build-$cfg.log 2>&1 || { echo "$cfg: build failed"; return 1; }
   rm -f $t.*; $Q -cpu $cpu -plugin $P,output=$t$popt -- $g > $OUT/guest-$cfg.log 2>&1; local rc=$?
   local tok=$(grep -o 'tokens: [0-9]* prefilled, [0-9]* generated' $OUT/guest-$cfg.log)
   # 100: every line as the numpy model and every answer right; 6: every line as the
   # numpy model but the answers wrong, which is what an untrained model does
   [ $rc = 100 ] || [ $rc = 6 ] || { echo "$cfg: guest exited $rc (100 or 6 = matches the numpy model)"; return 1; }
   rm -rf $d; ./run-sniper -n 1 -c riscv -d $d -g perf_model/dram/per_controller_bandwidth=$BW "${gargs[@]}" --traces=$t.app0.th0.sift > $OUT/sim-$cfg.log 2>&1 || { echo "$cfg: run-sniper failed"; return 1; }
   local n=$(echo "$tok" | awk '{print $2+$4}')
   python3 - "$cfg" "$n" "$BW" "$d/simulation/sim.stats" <<'PY'
import sys
cfg, n, bw, S = sys.argv[1], int(sys.argv[2]), sys.argv[3], sys.argv[4]
st = {}
for line in open(S):
    if ' = ' in line:
        k, v = line.split(' = ', 1); st[k.strip()] = v.strip().split(',')[0]
cyc, ins = float(st['performance_model.cycle_count']), int(st['performance_model.instruction_count'])
reads, writes = int(st.get('dram.reads', 0)), int(st.get('dram.writes', 0))
print('%-16s %d tokens  %10.0f cycles/token  %10.0f insn/token  dram/token %d reads + %d writes (%.1f MB at %s GB/s)' % (cfg, n, cyc / n, ins / n, reads / n, writes / n, (reads + writes) * 64 / n / 1e6, bw))
PY
}
for c in $CONFIGS; do one $c; done
